import { useState } from "react";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { registrarMensagem, verificarLimite } from "../lib/mensagens";
import { toast } from "react-toastify";

interface EnviarMensagemProps {
  clienteId: number;
  limite: number;
  onMensagemEnviada: () => void;
}

export default function EnviarMensagem({ clienteId, limite, onMensagemEnviada }: EnviarMensagemProps) {
  const [mensagem, setMensagem] = useState("");
  const [enviando, setEnviando] = useState(false);

  const handleEnviar = async () => {
    if (!mensagem.trim()) {
      toast.error("Digite uma mensagem");
      return;
    }

    setEnviando(true);

    try {
      // Verificar se o cliente ainda tem mensagens disponíveis
      await verificarLimite(clienteId, limite);

      // Simular envio da mensagem
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Registrar a mensagem enviada
      await registrarMensagem(clienteId);

      toast.success("Mensagem enviada com sucesso");
      setMensagem("");

      // Notificar o componente pai para atualizar a contagem
      onMensagemEnviada();
    } catch (error: any) {
      toast.error(error.message || "Erro ao enviar mensagem");
    } finally {
      setEnviando(false);
    }
  };

  return (
    <div className="flex flex-col gap-2">
      <div className="flex gap-2">
        <Input
          placeholder="Digite sua mensagem..."
          value={mensagem}
          onChange={(e) => setMensagem(e.target.value)}
          disabled={enviando}
        />
        <Button 
          onClick={handleEnviar}
          disabled={enviando}
        >
          {enviando ? "Enviando..." : "Enviar"}
        </Button>
      </div>
    </div>
  );
}
